  "$id": "https://github.com/mongodb/agent-skills/testing/evals.schema.json",
  "title": "Agent-skills QA eval cases (extended)",
  "description": "Schema for agent-skills/testing/<skill>/evals/evals.json. Extends the current judge-only shape (prompt/expected_output/expectations/files) with OPTIONAL functional-grading fields (seed, functional_check, trajectory_checks) so the QA harness can grade against a real MongoDB. All functional fields are optional and additive: existing knowledge-only cases validate unchanged. Fixtures referenced by `seed` live in the sibling `fixtures/` directory as deterministic <seed-name>.js scripts.",
  "x-fixtureContract": {
    "description": "The seed/fixture naming contract, declared here because it is shared across repos: agent-skills's validate-evals.mjs enforces it at authoring time and agent-skills-evals's solvers/seed_db.py resolves against it at run time. Both read these values rather than keeping their own copy, so the two cannot drift into a state where a case passes CI here and then fails to seed inside the harness.",
    "fixtureDir": "fixtures",
    "fixtureExtension": ".js",
    "reservedSeeds": [
      "clean_slate"
    ]
  },
  "type": "object",
  "required": [
    "skill_name",
    "evals"
  ],
  "additionalProperties": false,
  "properties": {
    "skill_name": {
      "type": "string",
      "description": "Skill directory name, e.g. mongodb-query-optimizer.",
      "pattern": "^[a-z0-9-]+$"
    },
    "evals": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/case"
      }
    }
  },
  "$defs": {
    "case": {
      "type": "object",
      "required": [
        "id"
      ],
      "additionalProperties": false,
      "patternProperties": {
        "^_": {
          "description": "Author comment key (e.g. _note); ignored by the harness."
        }
      },
      "description": "One test case. Single-turn cases use `prompt`; multi-turn cases use `workflow`.",
      "properties": {
        "id": {
          "type": "integer",
          "description": "Stable case id (unique within the skill; used to correlate results across runs)."
        },
        "name": {
          "type": "string",
          "description": "Optional human-readable case label."
        },
        "qa_skip_reason": {
          "type": "string",
          "minLength": 1,
          "description": "When present, excludes this case from QA evals; include the reason for the skip."
        },
        "prompt": {
          "type": "string",
          "description": "The task given to the agent (single-turn). Required unless `workflow` is present."
        },
        "workflow": {
          "type": "array",
          "description": "Multi-turn task: ordered turns. Alternative to `prompt`.",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": [
              "turn",
              "prompt"
            ],
            "additionalProperties": false,
            "properties": {
              "turn": {
                "type": "integer",
                "minimum": 1
              },
              "prompt": {
                "type": "string"
              }
            }
          }
        },
        "expected_output": {
          "type": "string",
          "description": "Narrative description of a correct answer. Lowest-priority judge target (used if no metadata assertions and no expectations)."
        },
        "expectations": {
          "type": "array",
          "description": "Skill-level checkable criteria. Judge target when present and no per-case metadata assertions exist.",
          "items": {
            "type": "string"
          }
        },
        "files": {
          "type": "array",
          "description": "Relative paths (under the evals dir) of asset files inlined into the prompt. Must stay INSIDE the evals dir: no leading '/' and no '..' segment. This is an eval-integrity rule, not a filesystem one -- the harness inlines these into the prompt (case_source.build_prompt), and the answer-echo lint deliberately excludes `files` from its overlap analysis because they are provided input data. A case that escaped upward to its own skills/<name>/SKILL.md would hand the agent the answer key with nothing flagging it.",
          "items": {
            "type": "string",
            "pattern": "^(?!/)(?!.*(^|/)\\.\\.(/|$)).+$"
          }
        },
        "seed": {
          "type": "string",
          "description": "Names a DB fixture in the sibling fixtures/ dir (fixtures/<seed>.js), applied to the sandbox MongoDB before the agent runs. 'clean_slate' = empty DB (no fixture file). Required for any functional_check that reads real data.",
          "pattern": "^[a-z0-9_]+$"
        },
        "functional_check": {
          "$ref": "#/$defs/functional_check"
        },
        "trajectory_checks": {
          "type": "array",
          "description": "Deterministic tool-use assertions on the agent's trajectory.",
          "items": {
            "$ref": "#/$defs/trajectory_check"
          }
        }
      },
      "oneOf": [
        {
          "required": [
